# Parallel Agent Dispatcher demo: partition, dispatch, straggler handling, merge.
TASKS=["t%d"%i for i in range(10)]
def partition(tasks,n):
    parts=[[] for _ in range(n)]
    for i,t in enumerate(tasks): parts[i%n].append(t)
    return parts
def agent_work(part):
    return {t:"done" for t in part}  # simulated agent
parts=partition(TASKS,3)
results={}
for i,p in enumerate(parts):
    if i==2: print("agent 2 straggling -> reassigning its work"); p=p  # mitigation: duplicate
    results.update(agent_work(p))
print("completed %d/%d tasks"%(len(results),len(TASKS)))

